/**
 * @suppress
 */
public object FfiConverterTypeLancatNode: FfiConverter<LancatNode, Long> {
    override fun lower(value: LancatNode): Long {
        return value.uniffiCloneHandle()
    }

    override fun lift(value: Long): LancatNode {
        return LancatNode(UniffiWithHandle, value)
    }

    override fun read(buf: ByteBuffer): LancatNode {
        return lift(buf.getLong())
    }

    override fun allocationSize(value: LancatNode) = 8UL

    override fun write(value: LancatNode, buf: ByteBuffer) {
        buf.putLong(lower(value))
    }
}



/**
 * Startup configuration (`NodeConfig`). Defaults match the desktop: TCP+UDP 47820, mDNS + UDP on.
 */
data class FfiConfig (
    /**
     * App-private directory for lancat.db, stickers, logs (Context.filesDir/lancat).
     */
    var `dataDir`: kotlin.String
    , 
    /**
     * Display name override (the phone model on Android: hostname is "localhost"). None = settings / hostname.
     */
    var `deviceName`: kotlin.String? = null 
    , 
    /**
     * TCP port. 47820 = default (falls back to 47821.. when taken), 0 = OS-assigned.
     */
    var `port`: kotlin.UShort = 47820u 
    , 
    var `udpPort`: kotlin.UShort = 47820u 
    , 
    /**
     * Where received files are written (a real directory). None = settings.receive_dir / Downloads.
     */
    var `receiveDir`: kotlin.String? = null 
    , 
    var `enableMdns`: kotlin.Boolean = true 
    , 
    var `enableUdp`: kotlin.Boolean = true 
    , 
    /**
     * Extra unicast probe targets "ip:udp_port" (tests).
     */
