sealed class FfiEvent {
    
    /**
     * A peer appeared / changed (online, name, unread, last message, blocked).
     */
    data class Peer(
        val `peer`: fan.lancat.core.ffi.FfiPeer) : FfiEvent()
        
    {
        

        companion object
    }
    
    data class PeerRemoved(
        val `peerId`: kotlin.String) : FfiEvent()
        
    {
        

        companion object
    }
    
    /**
     * A new message (incoming, or one we just created).
     */
    data class Message(
        val `message`: fan.lancat.core.ffi.FfiMessage) : FfiEvent()
        
    {
        

        companion object
    }
    
    /**
     * A message's status / body changed (delivered, transfer done / failed / paused...).
     */
    data class MessageUpdate(
        val `message`: fan.lancat.core.ffi.FfiMessage) : FfiEvent()
        
    {
        

        companion object
    }
    
    data class Typing(
        val `peerId`: kotlin.String, 
        val `typing`: kotlin.Boolean) : FfiEvent()
        
    {
        

        companion object
    }
    
    /**
     * Transfer progress (both directions), throttled by the core.
     */
    data class Progress(
        val `msgId`: kotlin.String, 
        val `peerId`: kotlin.String, 
        val `done`: kotlin.Long, 
        val `total`: kotlin.Long, 
        val `outgoing`: kotlin.Boolean) : FfiEvent()
        
    {
        

        companion object
    }
    
    data class HistoryCleared(
        val `peerId`: kotlin.String?) : FfiEvent()
        
    {
        

        companion object
    }
    
    data class Settings(
        val `settings`: fan.lancat.core.ffi.FfiSettings) : FfiEvent()
        
    {
        

        companion object
    }
    
    /**
     * kind = "inbound_blocked" (report set) | "recv_dir" (detail says why)
     */
    data class Alert(
        val `kind`: kotlin.String, 
        val `report`: fan.lancat.core.ffi.FfiInboundReport?, 
        val `detail`: kotlin.String) : FfiEvent()
        
    {
        

        companion object
    }
    
    /**
     * The event stream lagged and dropped `skipped` events: reload peers / open conversations.
     */
    data class Lagged(
        val `skipped`: kotlin.Long) : FfiEvent()
        
    {
        

        companion object
    }
    

    

    
    


    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeFfiEvent : FfiConverterRustBuffer<FfiEvent>{
    override fun read(buf: ByteBuffer): FfiEvent {
        return when(buf.getInt()) {
            1 -> FfiEvent.Peer(
                FfiConverterTypeFfiPeer.read(buf),
                )
            2 -> FfiEvent.PeerRemoved(
                FfiConverterString.read(buf),
                )
            3 -> FfiEvent.Message(
                FfiConverterTypeFfiMessage.read(buf),
                )
            4 -> FfiEvent.MessageUpdate(
                FfiConverterTypeFfiMessage.read(buf),
                )
            5 -> FfiEvent.Typing(
                FfiConverterString.read(buf),
                FfiConverterBoolean.read(buf),
                )
            6 -> FfiEvent.Progress(
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                FfiConverterLong.read(buf),
                FfiConverterLong.read(buf),
                FfiConverterBoolean.read(buf),
                )
            7 -> FfiEvent.HistoryCleared(
                FfiConverterOptionalString.read(buf),
                )
            8 -> FfiEvent.Settings(
                FfiConverterTypeFfiSettings.read(buf),
                )
            9 -> FfiEvent.Alert(
                FfiConverterString.read(buf),
                FfiConverterOptionalTypeFfiInboundReport.read(buf),
                FfiConverterString.read(buf),
                )
            10 -> FfiEvent.Lagged(
                FfiConverterLong.read(buf),
                )
            else -> throw RuntimeException("invalid enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: FfiEvent): ULong = when(value) {
        is FfiEvent.Peer -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterTypeFfiPeer.allocationSize(value.`peer`)
            )
        }
        is FfiEvent.PeerRemoved -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`peerId`)
            )
        }
        is FfiEvent.Message -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterTypeFfiMessage.allocationSize(value.`message`)
            )
        }
        is FfiEvent.MessageUpdate -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterTypeFfiMessage.allocationSize(value.`message`)
            )
        }
        is FfiEvent.Typing -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`peerId`)
                + FfiConverterBoolean.allocationSize(value.`typing`)
            )
        }
        is FfiEvent.Progress -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`msgId`)
                + FfiConverterString.allocationSize(value.`peerId`)
                + FfiConverterLong.allocationSize(value.`done`)
                + FfiConverterLong.allocationSize(value.`total`)
                + FfiConverterBoolean.allocationSize(value.`outgoing`)
            )
        }
        is FfiEvent.HistoryCleared -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterOptionalString.allocationSize(value.`peerId`)
            )
        }
        is FfiEvent.Settings -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterTypeFfiSettings.allocationSize(value.`settings`)
            )
        }
        is FfiEvent.Alert -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`kind`)
                + FfiConverterOptionalTypeFfiInboundReport.allocationSize(value.`report`)
                + FfiConverterString.allocationSize(value.`detail`)
            )
        }
        is FfiEvent.Lagged -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterLong.allocationSize(value.`skipped`)
            )
        }
    }

    override fun write(value: FfiEvent, buf: ByteBuffer) {
        when(value) {
            is FfiEvent.Peer -> {
                buf.putInt(1)
                FfiConverterTypeFfiPeer.write(value.`peer`, buf)
                Unit
            }
            is FfiEvent.PeerRemoved -> {
                buf.putInt(2)
                FfiConverterString.write(value.`peerId`, buf)
                Unit
            }
            is FfiEvent.Message -> {
                buf.putInt(3)
                FfiConverterTypeFfiMessage.write(value.`message`, buf)
                Unit
            }
            is FfiEvent.MessageUpdate -> {
                buf.putInt(4)
                FfiConverterTypeFfiMessage.write(value.`message`, buf)
                Unit
            }
            is FfiEvent.Typing -> {
                buf.putInt(5)
                FfiConverterString.write(value.`peerId`, buf)
                FfiConverterBoolean.write(value.`typing`, buf)
                Unit
            }
            is FfiEvent.Progress -> {
                buf.putInt(6)
                FfiConverterString.write(value.`msgId`, buf)
                FfiConverterString.write(value.`peerId`, buf)
                FfiConverterLong.write(value.`done`, buf)
                FfiConverterLong.write(value.`total`, buf)
                FfiConverterBoolean.write(value.`outgoing`, buf)
                Unit
            }
            is FfiEvent.HistoryCleared -> {
                buf.putInt(7)
                FfiConverterOptionalString.write(value.`peerId`, buf)
                Unit
            }
            is FfiEvent.Settings -> {
                buf.putInt(8)
                FfiConverterTypeFfiSettings.write(value.`settings`, buf)
                Unit
            }
            is FfiEvent.Alert -> {
                buf.putInt(9)
                FfiConverterString.write(value.`kind`, buf)
                FfiConverterOptionalTypeFfiInboundReport.write(value.`report`, buf)
                FfiConverterString.write(value.`detail`, buf)
                Unit
            }
            is FfiEvent.Lagged -> {
                buf.putInt(10)
                FfiConverterLong.write(value.`skipped`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
}







sealed class LancatException(message: String): kotlin.Exception(message) {
        
    /**
     * The core refused or failed; the message is the core's own (Chinese, user-facing) text.
     */
        class Core(message: String) : LancatException(message)
        
    /**
     * The node was shut down.
     */
        class Stopped(message: String) : LancatException(message)
        

    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<LancatException> {
        override fun lift(error_buf: RustBuffer.ByValue): LancatException = FfiConverterTypeLancatError.lift(error_buf)
    }
}

/**
 * @suppress
 */
public object FfiConverterTypeLancatError : FfiConverterRustBuffer<LancatException> {
    override fun read(buf: ByteBuffer): LancatException {
        
            return when(buf.getInt()) {
            1 -> LancatException.Core(FfiConverterString.read(buf))
            2 -> LancatException.Stopped(FfiConverterString.read(buf))
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
        
    }

    override fun allocationSize(value: LancatException): ULong {
        return 4UL
    }

    override fun write(value: LancatException, buf: ByteBuffer) {
        when(value) {
            is LancatException.Core -> {
                buf.putInt(1)
                Unit
            }
            is LancatException.Stopped -> {
                buf.putInt(2)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}





/**
 * Implemented in Kotlin. Called on the "lancat-events" thread, in order. Keep it quick (post to a
 * coroutine / flow); a slow listener only delays later events, it never blocks the core.
 */
public interface CoreListener {
    
    fun `onEvent`(`event`: FfiEvent)
    
    companion object
}



// Put the implementation in an object so we don't pollute the top-level namespace
internal object uniffiCallbackInterfaceCoreListener {
    internal object `onEvent`: UniffiCallbackInterfaceCoreListenerMethod0 {
        override fun callback(`uniffiHandle`: Long,`event`: RustBuffer.ByValue,`uniffiOutReturn`: Pointer,uniffiCallStatus: UniffiRustCallStatus,) {
            val uniffiObj = FfiConverterTypeCoreListener.handleMap.get(uniffiHandle)
            val makeCall = { ->
                uniffiObj.`onEvent`(
                    FfiConverterTypeFfiEvent.lift(`event`),
                )
            }
            val writeReturn = { _: Unit -> Unit }
            uniffiTraitInterfaceCall(uniffiCallStatus, makeCall, writeReturn)
        }
    }

    internal object uniffiFree: UniffiCallbackInterfaceFree {
        override fun callback(handle: Long) {
            FfiConverterTypeCoreListener.handleMap.remove(handle)
        }
    }

    internal object uniffiClone: UniffiCallbackInterfaceClone {
        override fun callback(handle: Long): Long {
            return FfiConverterTypeCoreListener.handleMap.clone(handle)
        }
    }

    internal var vtable = UniffiVTableCallbackInterfaceCoreListener.UniffiByValue(
        uniffiFree,
        uniffiClone,
        `onEvent`,
    )

    // Registers the foreign callback with the Rust side.
    // This method is generated for each callback interface.
    internal fun register(lib: UniffiLib) {
        lib.uniffi_lancat_ffi_fn_init_callback_vtable_corelistener(vtable)
    }
}

